using System;using System.Linq;using System.Reflection;using System.Text;using Verse;using PlayableRecreation;using PlayableRecreation.UI;using Chess;using Chess.Core;using UnityEngine;using PRQA;
public static class Command{public static string Run(){var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().First();var f=BindingFlags.Instance|BindingFlags.NonPublic;var w=(ChessGameWorker)typeof(Dialog_MiniGame).GetField("worker",f).GetValue(d);var game=(MiniGameDef)typeof(Dialog_MiniGame).GetField("game",f).GetValue(d);int before=GameComponent_Recreation.Current.ColonyRecord(game).Played;w.StartNew(2);var core=(ChessGame)typeof(ChessGameWorker).GetField("game",f).GetValue(w);var commit=typeof(ChessGameWorker).GetMethod("Commit",f);var moves=new[]{new[]{21,37},new[]{100,68},new[]{22,54},new[]{115,55}};foreach(var move in moves){var legal=core.Legal.Take(core.LegalCount).First(m=>m.From==move[0]&&m.To==move[1]);commit.Invoke(w,new object[]{legal,Time.realtimeSinceStartup});}Host.State["finishBefore"]=before;Host.State["finishWindow"]=d;return "Scripted legal Fool's Mate, both sides use actual worker Commit: "+string.Join(" ",core.Notation)+" result="+core.Result+" isOver="+w.IsOver+" won="+w.PlayerWon+" recordsBefore="+before;}}

